test('manual input cannot complete while paused',()=>{legacyLesson(0);sandbox.accept(60);assert.equal(run('pos'),0)});
test('all lesson metadata and finger arrays match',()=>{assert.equal(run('lessons.length'),210);run('lessons').forEach(l=>{assert.equal(l.seq.length,l.f.length);assert(l.f.every(f=>f===''||f>=1&&f<=5));if(l.beats)assert.equal(l.seq.length,l.beats.length);assert(l.seq.every(n=>n>=36&&n<=96))})});
test('no external runtime dependencies',()=>assert(!/<(?:script|link|img)[^>]+(?:src|href)=["']https?:/i.test(html)));
test('unique HTML element IDs',()=>{const ids=[...html.split('<script>')[0].matchAll(/\bid="([^"]+)"/g)].map(x=>x[1]).filter(x=>!x.includes('${'));assert.equal(new Set(ids).size,ids.length)});
