test('68 exercises render a complete grand staff',()=>{run('lessons').forEach((l,i)=>{sandbox.selectLesson(i);const svg=els.scoreSvg.innerHTML,grid=sandbox.scoreGrid(l);assert.deepEqual(Array.from(sandbox.scoreView().clefs),['treble','bass']);assert.equal((svg.match(/class="score-note /g)||[]).length,l.seq.length*(l.left?2:1),`lesson ${i+1} note count`);assert.equal((svg.match(/stroke="#a2aaa0"/g)||[]).length,10);assert.equal((svg.match(/class="score-measure-number"/g)||[]).length,grid.bars.length);const missing=l.left?[]:l.hand==='Right hand'?['bass']:l.hand==='Left hand'?['treble']:[];for(const clef of missing)assert.match(svg,new RegExp('class="score-empty-staff" data-clef="'+clef+'"'));assert(!/NaN|undefined/.test(svg));const ids=[...svg.matchAll(/\bid="([^"]+)"/g)].map(x=>x[1]);assert.equal(ids.length,new Set(ids).size);assert.match(els.lessonMeta.textContent,/\/ (68|142)/);assert(l.instruction&&l.tip&&l.fingering&&l.title)})});
test('short thick dashes are centered inside each silent measure and each empty staff',()=>{for(const hand of ['Right hand','Left hand']){const i=run('lessons.findIndex(l=>l.hand==='+JSON.stringify(hand)+'&&!l.left)');assert(i>=0);sandbox.selectLesson(i);const l=run('lessons[li]'),grid=sandbox.scoreGrid(l),missing=hand==='Right hand'?'bass':'treble',played=hand==='Right hand'?'treble':'bass',live=els.scoreSvg.innerHTML;assert.equal((live.match(/class="score-empty-staff"/g)||[]).length,grid.bars.length);assert(!live.includes('data-clef="'+played+'"'));for(let bar=0;bar<grid.bars.length;bar++){const cx=grid.firstX+(bar+.5)*grid.barWidth,y=missing==='bass'?210:90;assert(live.includes('x1="'+(cx-7)+'" y1="'+y+'" x2="'+(cx+7)+'" y2="'+y+'"'),l.id+' bar '+(bar+1));assert(live.includes('data-measure="'+(bar+1)+'"'))}assert.match(live,/stroke-width="4.5" stroke-linecap="round"/);sandbox.renderStaticSheet();assert.equal((els.staticScore.innerHTML.match(/class="score-empty-staff"/g)||[]).length,grid.bars.length)}const twoHand=run('lessons.findIndex(l=>l.left&&l.left.length)');sandbox.selectLesson(twoHand);const both=run('lessons[li]'),g=sandbox.scoreGrid(both);assert.equal((els.scoreSvg.innerHTML.match(/class="score-empty-staff"/g)||[]).length,g.bars.filter(b=>b.indices.length===0).length*2);const alternating={seq:[48,72],hand:'Alternating hands'};assert.match(sandbox.emptyStaffDashes(alternating,0,1),/data-clef="treble"/);assert.match(sandbox.emptyStaffDashes(alternating,1,2),/data-clef="bass"/);assert.equal(sandbox.emptyStaffDashes(alternating),'');assert.equal((sandbox.emptyStaffDashes({seq:[],hand:'Right hand'}).match(/class="score-empty-staff"/g)||[]).length,2)});
test('time signatures, fixed-width bars and measure numbers cover lessons and melodies',()=>{const known=[['repertoire-f-r-elise','3/8'],['repertoire-happy-birthday','3/4'],['repertoire-blue-danube','3/4'],['repertoire-minuet-in-g-bwv-anh-114','3/4'],['repertoire-prelude-in-c-bwv846','4/4'],['repertoire-greensleeves','6/8'],['lesson-28-level-3','3/8'],['lesson-26-level-3','3/4']];for(const [id,meter] of known){const l=run('catalogue.records['+JSON.stringify(id)+']');assert.equal(Array.from(sandbox.scoreMeter(l)).join('/'),meter,id)}for(const l of run('lessonLevels.flat().concat(melodyData)')){const grid=sandbox.scoreGrid(l),points=sandbox.scoreLayout(l),marks=sandbox.scoreMeasureDecorations(l,grid),meter=grid.meter.join('/');assert.equal(grid.measures.length,l.seq.length,l.title);assert(points.every((p,i)=>Number.isFinite(p.x)&&(!i||p.x>points[i-1].x)),l.title);assert.equal((marks.match(/class="score-time-signature"/g)||[]).length,2,l.title);assert.equal((marks.match(/class="score-final-barline"/g)||[]).length,2,l.title);assert.equal((marks.match(/class="score-measure-number"/g)||[]).length,grid.bars.length,l.title);assert(marks.includes('data-meter="'+meter+'"'));assert.equal((marks.match(/class="score-barline"/g)||[]).length,Math.max(0,grid.bars.length-1),l.title);for(let i=0;i<points.length;i++){const bar=grid.measures[i]-1,start=grid.firstX+bar*grid.barWidth;assert(points[i].x>=start+grid.pad-.001&&points[i].x<start+grid.barWidth-grid.pad+.001,l.title+' measure bounds')}}for(const [i,level] of [[0,0],[28,2],[68,0],[102,0]]){sandbox.selectLesson(i,level);const live=els.scoreSvg.innerHTML,l=run('lessons[li]');assert.match(live,/score-time-signature/);assert.match(live,/score-measure-number/);assert.match(live,/score-final-barline/);sandbox.renderStaticSheet();const sheet=els.staticScore.innerHTML,layout=sandbox.sheetLayout(l,sandbox.sheetContentWidth(els.staticScore),500),grid=sandbox.scoreGrid(l);assert.equal((sheet.match(/class="score-time-signature"/g)||[]).length,2);assert.equal((sheet.match(/class="score-measure-number"/g)||[]).length,grid.bars.length);assert(sheet.includes('score-final-barline'));assert.equal((sheet.match(/class="sheet-note"/g)||[]).length,l.seq.length*(l.left?2:1));assert.equal(layout.rows,Math.ceil(grid.bars.length/layout.barsPerRow))}sandbox.selectLesson(28,0);sandbox.selectLesson(0,0)});
test('measure timing grid anchors notes to onsets, not note counts, and preserves short final bars',()=>{const base={seq:[64,62,60,64,62,60,64,62,60],beats:[1,1,2,1,1,1,1,1,1],hand:'Right hand'};const grid=sandbox.scoreGrid(base),notes=sandbox.scoreLayout(base);assert(grid.bars.length>=3);assert.equal(grid.measures[0],1);assert.equal(grid.measures[3],2);assert.equal(grid.measures[7],3);const step=grid.barWidth-2*grid.pad;assert(Math.abs((notes[1].x-notes[0].x)-step/4)<1e-6);assert(Math.abs((notes[4].x-notes[3].x)-step/4)<1e-6);assert.equal(notes[0].x+grid.barWidth,notes[3].x);assert.equal(notes[3].x+grid.barWidth,notes[7].x);const first=grid.firstX,centers=grid.bars.map((_,i)=>first+(i+.5)*grid.barWidth);assert(centers.every((x,i)=>i===0||Math.abs(x-centers[i-1]-grid.barWidth)<.001));const oneNote={seq:[60,62,64,65,67],beats:[1,1,1,1,1],hand:'Right hand'},g=sandbox.scoreGrid(oneNote);assert.equal(g.bars.length,2);assert.equal(sandbox.scoreLayout(oneNote)[4].x,g.firstX+g.barWidth+g.pad);assert.equal(sandbox.scoreMeasureDecorations(oneNote,g).match(/score-measure-number/g).length,2);const space={seq:[60,62,64],steps:[1,7,1],beats:[1,1,1],hand:'Right hand'},e=sandbox.scoreGrid(space);assert.equal(e.bars.length,3);assert.equal(e.bars[1].indices.length,0);const decoration=sandbox.scoreMeasureDecorations(space,e);assert.match(decoration,/data-measure="2"/);assert.equal((decoration.match(/data-measure="2"/g)||[]).length,2);const short=sandbox.scoreGrid({seq:[60,62,64,65],steps:[.5,.5,.5,.5],beats:[.5,.5,.5,.5],hand:'Right hand'});assert.equal(short.barWidth,260)});
test('pitch-driven accidentals never place sharps on white keys',()=>{for(const l of run('lessonLevels.flat().concat(melodyData)')){for(const hand of [l.seq,...(l.left?[l.left]:[])]){const voice={...l,seq:hand};for(let i=0;i<hand.length;i++){const pitch=hand[i],sign=sandbox.scoreAccidental(voice,i);assert(['','♯','♭','♮'].includes(sign),l.title);if(sign==='♯'||sign==='♭')assert([1,3,6,8,10].includes(pitch%12),l.title+' accidental on a white key')}}}const sample={seq:[61,61,60,61,60],beats:[1,1,1,1,1],hand:'Right hand',accidentals:true};assert.equal(sandbox.scoreAccidental(sample,0),'♯');assert.equal(sandbox.scoreAccidental(sample,1),'');assert.equal(sandbox.scoreAccidental(sample,2),'♮');assert.equal(sandbox.scoreAccidental(sample,3),'♯');assert.equal(sandbox.scoreAccidental(sample,4),'');const byBar={seq:[61,60],beats:[4,1],hand:'Right hand',accidentals:true};assert.equal(sandbox.scoreAccidental(byBar,1),'');const white=sandbox.noteGlyph({x:134,y:108,clef:'treble',beats:1},0,{seq:[60],f:[1],hand:'Right hand',accidentals:true},true,true);assert(!white.includes('class="score-accidental"'));const sharp=sandbox.noteGlyph({x:134,y:108,clef:'treble',beats:1},0,{seq:[61],f:[2],hand:'Right hand',accidentals:true},true,true);assert.match(sharp,/class="score-accidental"[^>]*>♯<\/text>/);const flat=sandbox.noteGlyph({x:134,y:204,clef:'bass',beats:1},0,{seq:[70],f:[2],flats:true,hand:'Left hand',accidentals:true},true,true);assert.match(flat,/class="score-accidental"[^>]*>♭<\/text>/)});

