test('score note names use letter-only labels outside staff lines with separate fingering margins',()=>{const readY=(svg,cls)=>{const match=svg.match(new RegExp('class="'+cls+'" x="100" y="([^"]+)"'));assert(match,'missing '+cls);return Number(match[1])};const treble={seq:[71],f:[3],hand:'Right hand'},bass={seq:[50],f:[2],hand:'Left hand'};const high=sandbox.noteGlyph({x:100,y:48,clef:'treble',beats:1},0,treble,true,true),normal=sandbox.noteGlyph({x:100,y:84,clef:'treble',beats:1},0,treble,true,true),low=sandbox.noteGlyph({x:100,y:270,clef:'bass',beats:1},0,bass,true,true),middle=sandbox.noteGlyph({x:100,y:204,clef:'bass',beats:1},0,bass,true,true),highBass=sandbox.noteGlyph({x:100,y:168,clef:'bass',beats:1},0,bass,true,true);assert.equal(readY(normal,'score-finger-label'),28);assert.equal(readY(normal,'score-name-label'),46);assert.equal(readY(high,'score-finger-label'),12);assert.equal(readY(high,'score-name-label'),30);assert.equal(readY(middle,'score-finger-label'),274);assert.equal(readY(middle,'score-name-label'),160);assert.equal(readY(low,'score-finger-label'),302);assert.equal(readY(low,'score-name-label'),160);assert.equal(readY(highBass,'score-name-label'),150);for(const sample of [normal,high]){const nameY=readY(sample,'score-name-label'),fingerY=readY(sample,'score-finger-label');assert(nameY+3<60,'treble note letter must be entirely above the staff');assert(fingerY+4<nameY-11,'treble finger number must be separated from the letter')}for(const sample of [middle,low,highBass]){const nameY=readY(sample,'score-name-label'),fingerY=readY(sample,'score-finger-label');assert(nameY+3<180,'bass note letter must be entirely above the staff');assert(fingerY-11>228,'bass finger number must be entirely below the staff')}const middleC={seq:[60],f:[1],hand:'Right hand'},c=sandbox.noteGlyph({x:100,y:120,clef:'treble',beats:1},0,middleC,true,true);assert.match(c,/class="score-name-label"[^>]*>C<\/text>/);assert(!c.includes('>C4</text>'));const sharp=sandbox.noteGlyph({x:100,y:108,clef:'treble',beats:1},0,{seq:[61],f:[2],hand:'Right hand'},true,true),flat=sandbox.noteGlyph({x:100,y:204,clef:'bass',beats:1},0,{seq:[70],f:[3],hand:'Left hand',flats:true},true,true);assert.match(sharp,/>C♯<\/text>/);assert.match(flat,/>B♭<\/text>/);assert.match(normal,/paint-order="stroke"/);assert.doesNotMatch(sandbox.noteGlyph({x:100,y:84,clef:'treble',beats:1},0,treble,false,true),/class="score-name-label"/);for(const i of [0,14,68,118,209]){sandbox.selectLesson(i);const l=run('lessons[li]'),score=els.scoreSvg.innerHTML,view=sandbox.scoreView(),names=[...score.matchAll(/class="score-name-label"[^>]*>([^<]+)<\/text>/g)].map(m=>m[1]);assert.equal(names.length,l.seq.length*(l.left?2:1));assert(names.every(x=>/^[A-G][♯♭]?$/.test(x)),l.title+' has an octave number on its notation');const trebleNotes=sandbox.scoreLayout(l).filter(p=>p.clef==='treble');for(const p of trebleNotes)assert(view.y<=sandbox.scoreFingerY(p.y,p.clef)-13,'treble margin label clipped');sandbox.renderStaticSheet();const sheetNames=[...els.staticScore.innerHTML.matchAll(/class="score-name-label"[^>]*>([^<]+)<\/text>/g)].map(m=>m[1]);assert.equal(sheetNames.length,names.length);assert(sheetNames.every(x=>/^[A-G][♯♭]?$/.test(x)))}});
