function prepareMic(){sandbox.stopMic();run('ctx=null;mode="mic"');sandbox.window.isSecureContext=true;delete sandbox.document.permissionsPolicy;delete sandbox.document.featurePolicy;sandbox.window.AudioContext=AudioMock;delete sandbox.navigator.mediaDevices;timers.clear();}
function fakeMicStream(){let count=0;const track={stop(){count++}};return {getTracks:()=>[track],getAudioTracks:()=>[track],get stopped(){return count}}}
async function settleUntil(fn){for(let i=0;i<20&&!fn();i++)await Promise.resolve();assert(fn(),'async phase not reached')}
function timerAt(ms){return [...timers.keys()].find(id=>timerDelays.get(id)===ms)}
await asyncTest('microphone permission request precedes blocked audio resume',async()=>{prepareMic();const events=[];class BlockedAudio extends AudioMock{constructor(){super();this.state='suspended'}resume(){events.push('resume');return new Promise(()=>{})}}sandbox.window.AudioContext=BlockedAudio;const s=fakeMicStream();sandbox.navigator.mediaDevices={getUserMedia(){events.push('getUserMedia');return Promise.resolve(s)}};const pending=sandbox.enableMic();assert.deepEqual(events,['getUserMedia']);await settleUntil(()=>events.includes('resume'));assert.deepEqual(events,['getUserMedia','resume']);assert.equal(el('mic').textContent,'Cancel microphone request');sandbox.stopMic();assert.equal(await pending,false);assert.equal(s.stopped,1);assert.equal(run('micPending'),false);assert.equal(timers.size,0)});
await asyncTest('insecure contexts explain why no prompt can appear',async()=>{prepareMic();let calls=0;sandbox.window.isSecureContext=false;sandbox.navigator.mediaDevices={getUserMedia(){calls++;return Promise.resolve(fakeMicStream())}};assert.equal(await sandbox.enableMic(),false);assert.equal(calls,0);assert.match(el('status').textContent,/secure browser context/);assert.equal(el('status').textContent,el('settingsStatus').textContent);assert.equal(run('micPending'),false)});
await asyncTest('permissions policy denial is reported without requesting audio',async()=>{prepareMic();let calls=0;sandbox.document.permissionsPolicy={allowsFeature(name){assert.equal(name,'microphone');return false}};sandbox.navigator.mediaDevices={getUserMedia(){calls++;return Promise.resolve(fakeMicStream())}};assert.equal(await sandbox.enableMic(),false);assert.equal(calls,0);assert.match(el('status').textContent,/embedded page blocks microphone access/);assert.equal(run('micPending'),false)});
await asyncTest('pending request shows waiting guidance and remains cancellable',async()=>{prepareMic();let resolve;sandbox.navigator.mediaDevices={getUserMedia:()=>new Promise(r=>resolve=r)};const pending=sandbox.enableMic();assert.equal(run('micPending'),true);assert.equal(el('mic').disabled,false);fireTimer(timerAt(12000));assert.match(el('status').textContent,/Still waiting/);assert.equal(run('micPending'),true);sandbox.stopMic();assert.equal(await pending,false);assert.equal(run('micPending'),false);assert.equal(timers.size,0);const s=fakeMicStream();resolve(s);await settleUntil(()=>s.stopped===1);assert.equal(run('stream'),null)});
await asyncTest('audio startup timeout stops permission-granted stream',async()=>{prepareMic();class BlockedAudio extends AudioMock{constructor(){super();this.state='suspended'}resume(){return new Promise(()=>{})}}sandbox.window.AudioContext=BlockedAudio;const s=fakeMicStream();sandbox.navigator.mediaDevices={getUserMedia:()=>Promise.resolve(s)};const pending=sandbox.enableMic();await settleUntil(()=>timerAt(5000));fireTimer(timerAt(5000));assert.equal(await pending,false);assert.equal(s.stopped,1);assert.equal(run('stream'),null);assert.equal(run('micPending'),false);assert.match(el('status').textContent,/audio engine did not start/);assert.equal(timers.size,0)});
await asyncTest('denied permission cleans up and gives retry guidance',async()=>{prepareMic();sandbox.navigator.mediaDevices={getUserMedia:()=>Promise.reject(Object.assign(new Error('denied'),{name:'NotAllowedError'}))};assert.equal(await sandbox.enableMic(),false);assert.equal(run('micPending'),false);assert.equal(timers.size,0);assert.match(el('status').textContent,/Allow this site if it is listed as blocked/);assert.equal(el('mic').textContent,'Try microphone again')});
await asyncTest('successful microphone starts without waiting for device enumeration',async()=>{prepareMic();const s=fakeMicStream();sandbox.navigator.mediaDevices={getUserMedia:()=>Promise.resolve(s),enumerateDevices:()=>new Promise(()=>{})};assert.equal(await sandbox.enableMic(),true);assert.equal(run('stream'),s);assert.equal(run('micPending'),false);assert.equal(timers.size,0);assert.equal(el('micState').textContent,'Listening locally');sandbox.stopMic();assert.equal(s.stopped,1)});
await asyncTest('cancelled request cannot overwrite a successful retry',async()=>{prepareMic();let firstResolve;sandbox.navigator.mediaDevices={getUserMedia:()=>new Promise(r=>firstResolve=r)};const first=sandbox.enableMic();sandbox.stopMic();const secondStream=fakeMicStream();sandbox.navigator.mediaDevices.getUserMedia=()=>Promise.resolve(secondStream);const second=sandbox.enableMic();assert.equal(await first,false);assert.equal(await second,true);const firstStream=fakeMicStream();firstResolve(firstStream);await settleUntil(()=>firstStream.stopped===1);assert.equal(run('stream'),secondStream);assert.equal(el('micState').textContent,'Listening locally');assert.equal(secondStream.stopped,0);sandbox.stopMic()});
