test('quiet-room calibration uses robust percentile and pauses note acceptance',()=>{legacyLesson(1);run('pos=1;running=true;mode="mic";ignoreUntil=0;calibrationUntil=11500;calibrationSamples=[]');for(let i=0;i<20;i++)sandbox.processPitch(293.66477,i===19?.03:.002,10000+i*32);assert.equal(run('pos'),1);sandbox.finishCalibration();assert.equal(+el('sensitivity').value,6);assert.equal(run('calibrationUntil'),0);assert.equal(el('calibrate').disabled,false);assert.match(el('status').textContent,/Room calibrated/);run('calibrationSamples=Array(20).fill(0)');sandbox.finishCalibration();assert.equal(+el('sensitivity').value,1);run('calibrationSamples=Array(20).fill(.1)');sandbox.finishCalibration();assert.equal(+el('sensitivity').value,1);assert.match(el('status').textContent,/too noisy/);el('sensitivity').value='4'});
