test('sheet opens focused and controls restore without losing notes',()=>{legacyLesson(5);sandbox.showSheet();const count=()=>[...el('staticScore').innerHTML.matchAll(/id="sheetNote(\d+)"/g)].length;assert(el('sheetScreen').classList.contains('sheet-focus'));assert.equal(el('sheetControls').hidden,false);assert.equal(el('sheetFocus').attrs['aria-pressed'],'true');assert.equal(count(),17);el('sheetControls').onclick();assert.equal(el('sheetScreen').classList.contains('sheet-focus'),false);assert.equal(el('sheetControls').hidden,true);assert.equal(el('sheetFocus').attrs['aria-pressed'],'false');assert.equal(count(),17);el('sheetFocus').onclick();assert(el('sheetScreen').classList.contains('sheet-focus'));assert.equal(count(),17)});
await asyncTest('connecting disables Start until microphone startup completes',async()=>{prepareMic();let resolve;sandbox.navigator.mediaDevices={getUserMedia:()=>new Promise(r=>resolve=r)};const p=sandbox.openLesson(0,0);assert.equal(el('start').disabled,true);assert.equal(el('start').textContent,'Connecting…');resolve(fakeMicStream());await p;assert.equal(el('start').disabled,false);assert.equal(run('running'),true);sandbox.stopMic()});
await asyncTest('navigation during connection restores controls without stale retry label',async()=>{prepareMic();let resolve;sandbox.navigator.mediaDevices={getUserMedia:()=>new Promise(r=>resolve=r)};const p=sandbox.openLesson(0,0);assert.equal(el('start').disabled,true);sandbox.chooseMode('touch');await sandbox.openLesson(1,0);assert.equal(el('start').disabled,false);const label=el('start').textContent;await p;const s=fakeMicStream();resolve(s);await settleUntil(()=>s.stopped===1);assert.equal(el('start').textContent,label);assert.equal(run('li'),1);assert.equal(run('currentLevel'),0);assert.equal(run('running'),true)});

function strikeWave({attacks=[.1],seconds=2,beating=false,noiseClicks=false,pure=false}={}){const sr=48000,f=261.625565;let seed=17;return Float32Array.from({length:sr*seconds},(_,i)=>{const t=i/sr;let v=0;for(const at of attacks){const age=t-at;if(age<0)continue;const env=(1-Math.exp(-age*1200))*Math.exp(-age*1.9);if(pure)v+=.12*env*Math.sin(2*Math.PI*f*age);else{for(let h=1;h<=8;h++){const amp=[1,.28,.14,.08,.05,.035,.02,.015][h-1]+(h>3?.16*Math.exp(-age*65):0);v+=.1*env*amp*Math.sin(2*Math.PI*f*h*age+.13*h)}if(beating)v+=.06*env*Math.sin(2*Math.PI*(f+1.7)*age)}}seed=(Math.imul(seed,1664525)+1013904223)>>>0;if(noiseClicks&&[.4,.75,1.1].some(at=>t>=at&&t<at+.004))v+=(seed/4294967296-.5)*.3;return v})}
function simulateStrikes(options){legacyLesson(0);run('screen="studio";mode="mic";running=true;ignoreUntil=0;noteCooldownUntil=0;attackState=createAttackTracker();usedStrikeId=0;strikeCandidate=null;quietSince=0');el('response').value='balanced';el('tuning').value='440';el('tolerance').value='45';el('sensitivity').value='4';const wave=strikeWave(options),sr=48000,observed=[];let previousPos=0;for(let t=0;t*48<wave.length;t+=16){const end=Math.floor(t*48),buf=new Float32Array(4096),start=Math.max(0,end-4096);buf.set(wave.subarray(start,end),4096-(end-start));const event=sandbox.trackAttack(run('attackState'),buf,sr,t,.004),p=sandbox.detectPitch(buf,sr);let short=null;if(event&&event.id>run('usedStrikeId')&&t-event.time>=40&&t-event.time<=240)short=sandbox.detectPitch(buf.subarray(buf.length-1920),sr);sandbox.processPitch(p.freq,p.rms,t,{event,shortFreq:short?.freq||0,shortRms:short?.rms||0,shortConfidence:short?.confidence||0});if(run('pos')!==previousPos){observed.push({t,pos:run('pos'),eventId:event?.id});previousPos=run('pos')}}return {pos:run('pos'),onsets:run('attackState.id'),observed}}
test('single decaying piano note never double-counts',()=>{const r=simulateStrikes({seconds:2});assert.equal(r.pos,1,JSON.stringify(r))});
test('single beating piano note never double-counts',()=>{const r=simulateStrikes({seconds:2.5,beating:true});assert.equal(r.pos,1,JSON.stringify(r))});
test('single note plus brief noise clicks never double-counts',()=>{const r=simulateStrikes({seconds:2,noiseClicks:true});assert.equal(r.pos,1,JSON.stringify(r))});
for(const gap of [.2,.25,.3])test(`fresh repeated piano attacks with ringing tails, ${gap*1000}ms apart`,()=>{const r=simulateStrikes({attacks:[.1,.1+gap,.1+2*gap,.1+3*gap],seconds:1.8});assert.equal(r.pos,4,JSON.stringify(r))});
test('one strike event is consumed only once',()=>{legacyLesson(0);run('screen="studio";mode="mic";running=true;ignoreUntil=0;noteCooldownUntil=0;attackState.id=1');const meta={event:{id:1,time:1000,beforeRms:.02},shortFreq:261.62556,shortRms:.1,shortConfidence:.99};sandbox.processPitch(261.62556,.1,1040,meta);sandbox.processPitch(261.62556,.1,1070,meta);assert.equal(run('pos'),1);for(let t=1100;t<1500;t+=30)sandbox.processPitch(261.62556,.1,t,meta);assert.equal(run('pos'),1)});

test('single beating note with brief noise clicks never double-counts',()=>{const r=simulateStrikes({seconds:2.5,beating:true,noiseClicks:true});assert.equal(r.pos,1,JSON.stringify(r))});
test('near-threshold decay trough does not arm a repeated note',()=>{legacyLesson(0);run('screen="studio";mode="mic";running=true;ignoreUntil=0;noteCooldownUntil=0');sandbox.processPitch(261.62556,.1,1000);sandbox.processPitch(261.62556,.1,1070);for(const t of [1200,1280,1360])sandbox.processPitch(261.62556,.003,t);for(const t of [1450,1520,1650])sandbox.processPitch(261.62556,.006,t);assert.equal(run('pos'),1)});
function readyResults(){prepareMic();legacyLesson(0);const s=fakeMicStream();sandbox.resultStream=s;run('stream=resultStream;mode="mic";pos=4;tries=4');el('handsFreeReplay').checked=true;sandbox.navigate('results');return s}
test('held finishing note cannot trigger hands-free replay',()=>{readyResults();for(let t=10000;t<=14500;t+=80)sandbox.processPitch(261.62556,.1,t);assert.equal(run('screen'),'results');assert.equal(run('resultReplay.phase'),'ready');assert.equal(run('pos'),4)});
test('strike before cooldown boundary cannot arm results replay',()=>{readyResults();run('attackState.id=1');const meta={event:{id:1,time:11990,beforeRms:.01},shortFreq:261.62556,shortRms:.1,shortConfidence:.99};for(const t of [12040,12080,12120])sandbox.processPitch(261.62556,.1,t,meta);assert.equal(run('resultReplay.phase'),'ready')});
await asyncTest('fresh results note waits for release and is excluded from replay totals',async()=>{const old=readyResults(),fresh=fakeMicStream();sandbox.navigator.mediaDevices={getUserMedia:()=>Promise.resolve(fresh)};sandbox.processPitch(0,0,12000);sandbox.processPitch(0,0,12120);sandbox.processPitch(293.66477,.1,12200);sandbox.processPitch(293.66477,.1,12280);assert.equal(run('resultReplay.phase'),'release');assert.equal(run('screen'),'results');assert.equal(run('pos'),4);sandbox.processPitch(293.66477,.1,12500);assert.equal(run('screen'),'results');sandbox.processPitch(0,0,12600);sandbox.processPitch(0,0,12770);assert.equal(run('screen'),'results');sandbox.processPitch(0,0,12790);await settleUntil(()=>run('running'));assert.equal(run('screen'),'studio');assert.equal(run('pos'),0);assert.equal(run('tries'),0);assert.equal(old.stopped,1);sandbox.stopMic()});
test('leaving results cancels replay and retained microphone',()=>{const s=readyResults();sandbox.processPitch(0,0,12000);sandbox.processPitch(0,0,12120);sandbox.processPitch(261.62556,.1,12200);sandbox.processPitch(261.62556,.1,12280);assert.equal(run('resultReplay.phase'),'release');sandbox.navigate('course');assert.equal(run('resultReplay'),null);assert.equal(s.stopped,1);sandbox.processPitch(0,0,13000);sandbox.processPitch(0,0,13200);assert.equal(run('screen'),'course')});
test('disabled hands-free replay does not retain microphone on results',()=>{readyResults();el('handsFreeReplay').checked=false;el('handsFreeReplay').onchange();assert.equal(run('resultReplay'),null);assert.equal(run('stream'),null);assert.equal(el('replayCue').hidden,true);el('handsFreeReplay').checked=true});

